pipeline {
    agent any

    options {
        timeout(time: 30, unit: 'MINUTES')
        buildDiscarder(logRotator(numToKeepStr: '20'))
        ansiColor('xterm')
    }

    environment {
        APP_NAME    = 'trak-api'
        IMAGE_TAG   = "${env.BUILD_NUMBER}-${env.GIT_COMMIT.take(7)}"
    }

    stages {
        stage('Lint & Static Analysis') {
            steps {
                echo "Running static linters on ${env.APP_NAME}..."
                sh 'echo Linters passed!'
            }
        }

        stage('Unit Tests') {
            steps {
                echo 'Executing test suite...'
                sh 'echo Tests passed with 100% coverage!'
            }
        }

        stage('Build & Push Container') {
            steps {
                echo "Building container image: ${env.APP_NAME}:${env.IMAGE_TAG}"
                sh 'echo Container image built successfully.'
            }
        }
    }

    post {
        always {
            cleanWs()
        }
        success {
            echo '🎉 Pipeline Succeeded!'
        }
        failure {
            echo '❌ Pipeline Failed!'
        }
    }
}

pipeline {
    agent none
    stages {
        stage('Check Controller Status') {
            agent any
            steps {
                echo "Jenkins Build Number: ${env.BUILD_NUMBER}"
                echo "Node Name: ${env.NODE_NAME}"
            }
        }
    }
}

pipeline {
    agent any
    stages {
        stage('Inspect Environment') {
            steps {
                echo "Jenkins URL: ${env.JENKINS_URL}"
            }
        }
    }
}

pipeline {
    agent any
    stages {
        stage('Demonstrate Pipeline-as-Code') {
            steps {
                echo 'This stage is version-controlled inside Git!'
            }
        }
    }
}

options {
    buildDiscarder(logRotator(numToKeepStr: '10'))
}

# 02 — Declarative Pipeline Syntax Standard

## 🎯 Required Structure
```groovy
pipeline {
    agent any
    stages {
        stage('Example') {
            steps {
                echo 'Hello'
            }
        }
    }
}
```

pipeline {
    agent any
    stages {
        stage('Build') {
            steps {
                sh 'echo Compiling application...'
            }
        }
    }
}

options {
    timeout(time: 15, unit: 'MINUTES')
}

pipeline {
    agent any
    stages {
        stage('Dynamic Stage Execution') {
            steps {
                script {
                    def targets = ['dev', 'stage', 'prod']
                    for (env_name in targets) {
                        echo "Target Environment: ${env_name}"
                    }
                }
            }
        }
    }
}

script {
    try {
        sh 'echo Running step...'
    } catch (Exception e) {
        echo "Caught exception: ${e.message}"
    }
}

# 04 — Docker Container Agents

## 🎯 Ephemeral Build Environments
```groovy
agent {
    docker {
        image 'golang:1.22-alpine'
        args '-v /tmp:/tmp'
    }
}
```

pipeline {
    agent {
        docker {
            image 'node:20-alpine'
            reuseNode true
        }
    }
    stages {
        stage('Check Node Version') {
            steps {
                sh 'node --version'
            }
        }
    }
}

agent {
    node {
        label 'linux-builder'
    }
}

pipeline {
    agent any
    stages {
        stage('Parallel Quality Checks') {
            parallel {
                stage('Unit Tests') {
                    steps { echo 'Running Unit Tests...' }
                }
                stage('Security Scan') {
                    steps { echo 'Running SAST Security Scan...' }
                }
            }
        }
    }
}

parallel {
    failFast true
    stage('Test Branch A') { steps { echo 'Testing A' } }
    stage('Test Branch B') { steps { echo 'Testing B' } }
}

pipeline {
    agent any
    environment {
        DEPLOY_TIER = 'production'
    }
    stages {
        stage('Read Environment') {
            steps {
                echo "Target Tier: ${env.DEPLOY_TIER}"
            }
        }
    }
}

parameters {
    string(name: 'VERSION', defaultValue: '1.0.0', description: 'Release Version')
}

pipeline {
    agent any
    stages {
        stage('Access Secret') {
            steps {
                echo 'Credentials are masked in console output: ****'
            }
        }
    }
}

withCredentials([usernamePassword(credentialsId: 'registry-login', usernameVariable: 'USER', passwordVariable: 'PASS')]) {
    sh 'echo Authenticating as ${USER}...'
}

pipeline {
    agent any
    stages {
        stage('Execution') {
            steps { echo 'Job running...' }
        }
    }
    post {
        always {
            echo 'Cleaning up workspace...'
            cleanWs()
        }
    }
}

post {
    failure {
        echo '⚠️ Alert: Pipeline execution failed on stage!'
    }
}

pipeline {
    agent none
    stages {
        stage('Deploy to Production') {
            when {
                beforeAgent true
                branch 'main'
            }
            agent any
            steps {
                echo 'Deploying main branch to production...'
            }
        }
    }
}

when {
    tag pattern: 'release-*', comparator: 'GLOB'
}

